  "items": [
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–2018",
      "url_or_doi": "https://doi.org/10.4232/1.13775",
      "justification": "One of the most relevant datasets for studying social behaviour and attitudes in Germany during the 2010s. ALLBUS is a representative population survey conducted every two years. It includes observations from 2010, 2012, 2014, 2016, and 2018, covering social values, political attitudes, religion, social inequality, interpersonal trust, family relationships, and social participation. Particularly useful for examining changes in German society throughout the decade."
    },
    {
      "title": "German General Social Survey (ALLBUS) – Cumulation 1980–2023",
      "url_or_doi": "https://doi.org/10.4232/1.14696",
      "justification": "A cumulative dataset containing multiple decades of German population survey data, including the entire 2010s. It provides information on social attitudes, values, behaviour, demographic characteristics, political preferences, and societal change. Researchers can select observations from 2010–2019 to investigate trends in German social behaviour and compare them with earlier or later periods."
    },
    {
      "title": "European Social Survey (ESS) – Rounds 5–9, 2010–2018",
      "url_or_doi": "https://ess.nsd.no/en/series/321b06ad-1b98-4b7d-93ad-ca8a24e8788a",
      "justification": "A major cross-national survey measuring social attitudes, beliefs, values, and behaviour across Europe, including Germany. The 2010, 2012, 2014, 2016, and 2018 rounds provide information on interpersonal trust, political participation, immigration attitudes, social inequality, subjective well-being, discrimination, and institutional confidence. Researchers can filter observations to Germany and examine changes throughout the 2010s or compare German attitudes with those in other European countries."
    },
    {
      "title": "German Socio-Economic Panel (SOEP-Core) – Data 1984–2019, International Edition",
      "url_or_doi": "https://doi.org/10.5684/soep.core.v36i",
      "justification": "A longitudinal household panel dataset covering Germany throughout the 2010s. It contains information on household composition, social relationships, employment, income, education, subjective well-being, life satisfaction, migration, and individual attitudes. Its longitudinal structure makes it especially valuable for studying how social behaviours and attitudes changed within individuals and households between 2010 and 2019."
    },
    {
      "title": "GESIS Panel – Population Sample, 2013 Onward",
      "url_or_doi": "https://www.gesis.org/en/gesis-panel/data-access/data-access-gesis-panelpop",
      "justification": "A longitudinal survey of Germany's adult German-speaking population, with data collection beginning in 2013. Its repeated surveys investigate social and political participation, environmental attitudes, personal well-being, social relationships, and other aspects of everyday life. The 2013–2019 observations are particularly useful for analysing individual-level changes in attitudes and behaviour during the second half of the decade."
    },
    {
      "title": "International Social Survey Programme (ISSP) – Annual Modules 2010–2019",
      "url_or_doi": "https://issp.org/data-download/",
      "justification": "An international survey programme containing German observations across multiple thematic modules during the 2010s. Relevant modules include Environment (2010), Family and Changing Gender Roles (2012), National Identity (2013), Citizenship (2014), Work Orientations (2015), Role of Government (2016), Social Networks (2017), Religion (2018), and Social Inequality (2019). Particularly useful for examining specific dimensions of social attitudes and comparing Germany with other countries."
    },
    {
      "title": "World Values Survey (WVS) – Wave 6, 2010–2014, and Wave 7, 2017–2022",
      "url_or_doi": "https://www.worldvaluessurvey.org/AJDocumentationSmpl.jsp?CndWAVE=-1&INID=&SAID=-1",
      "justification": "A major international survey investigating cultural values, social norms, beliefs, and political attitudes. Its time-series database incorporates waves covering the 2010s and includes German survey observations. Topics include family values, religion, interpersonal trust, tolerance, gender equality, democratic attitudes, and social participation. Suitable for studying cultural and attitudinal change in Germany and comparing findings internationally."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Pre-election Cross Section 2017",
      "url_or_doi": "https://doi.org/10.4232/1.14290",
      "justification": "A representative election survey conducted in Germany between July and September 2017. It investigates political preferences, voting intentions, political attitudes, electoral behaviour, and perceptions of political parties and candidates. Useful for studying political dimensions of social attitudes in Germany during the 2010s, particularly political participation, ideological divisions, and public opinion around the 2017 federal election."
    },
    {
      "title": "International Social Survey Programme (ISSP) – Social Inequality V, 2019",
      "url_or_doi": "https://issp.org/data-download/",
      "justification": "A thematic international survey dataset examining public perceptions of inequality and social stratification in 2019, including German respondents. It investigates attitudes toward income differences, social mobility, fairness, distributive justice, and government responsibility for reducing inequality. Particularly relevant for understanding German perceptions of social class and economic inequality at the end of the 2010s."
    },
    {
      "title": "International Social Survey Programme (ISSP) – Social Networks and Social Resources III, 2017",
      "url_or_doi": "https://issp.org/data-download/",
      "justification": "A cross-national survey module from 2017 covering social networks and access to social resources, with German participation. It examines social contacts, interpersonal relationships, support networks, and social capital. Especially useful for investigating patterns of social interaction, community connections, and access to informal support among people living in Germany."
    },
    {
      "title": "International Social Survey Programme (ISSP) – Religion IV, 2018",
      "url_or_doi": "https://issp.org/data-download/",
      "justification": "An international survey module examining religious beliefs, practices, and attitudes in 2018, including respondents in Germany. It provides information on religious affiliation, participation in religious activities, spirituality, religious tolerance, and relationships between religion and society. Useful for analysing secularisation, religious diversity, and the influence of religious values on German social attitudes during the late 2010s."
    },
    {
      "title": "International Social Survey Programme (ISSP) – Family and Changing Gender Roles IV, 2012",
      "url_or_doi": "https://issp.org/data-download/",
      "justification": "A comparative social survey conducted in 2012 that includes Germany and focuses on family structures, gender expectations, employment, childcare, and household responsibilities. It is particularly relevant for studying attitudes toward marriage, parenting, gender equality, and the division of domestic labour in Germany during the early 2010s."
    },
    {
      "title": "International Social Survey Programme (ISSP) – Environment III, 2010",
      "url_or_doi": "https://issp.org/data-download/",
      "justification": "A survey module from 2010 containing German data on environmental beliefs, attitudes, concerns, and reported behaviour. It investigates perceptions of environmental risks, willingness to make personal sacrifices for environmental protection, and confidence in environmental policies. Useful for examining environmental awareness and the relationship between social values and environmentally responsible behaviour at the beginning of the decade."
    },
    {
      "title": "Pairfam – German Family Panel, Waves 2008/2009–2021/2022",
      "url_or_doi": "https://www.pairfam.de/",
      "justification": "A longitudinal German panel study focusing on intimate relationships, partnerships, family formation, parenting, and intergenerational relationships. Its annual waves cover the entire 2010s, allowing researchers to study changing family attitudes, partnership behaviour, fertility intentions, relationship satisfaction, and social support. Particularly valuable for research on interpersonal behaviour and evolving family norms in Germany."
    }
  ]
}
